import json, math, time
import urllib.parse, urllib.request
from datetime import datetime, date, timedelta, timezone

UA = 'codex-cli'
BASE = 'https://api.github.com/search/issues'

# Respect low unauthenticated rate limits
REQUEST_DELAY = 1.0


def request_json(url):
    req = urllib.request.Request(
        url,
        headers={
            'Accept': 'application/vnd.github+json',
            'User-Agent': UA,
        },
    )
    with urllib.request.urlopen(req) as r:
        return json.load(r)


def search(query):
    per_page = 100
    items = []
    page = 1
    total = None
    while True:
        url = f"{BASE}?q={urllib.parse.quote(query)}&per_page={per_page}&page={page}"
        data = request_json(url)
        if total is None:
            total = int(data.get('total_count', 0))
        batch = data.get('items', [])
        items.extend(batch)
        if len(items) >= total or not batch:
            break
        page += 1
        time.sleep(REQUEST_DELAY)
    return items, total


def search_range(query_base, start_date, end_date):
    query = f"{query_base} created:{start_date}..{end_date}"
    items, total = search(query)
    if total <= 1000:
        return items

    start = date.fromisoformat(start_date)
    end = date.fromisoformat(end_date)
    if start >= end:
        return items

    mid = start + (end - start) // 2
    left = search_range(query_base, start.isoformat(), mid.isoformat())
    right = search_range(query_base, (mid + timedelta(days=1)).isoformat(), end.isoformat())
    return left + right


def parse_iso(dt):
    if not dt:
        return None
    return datetime.fromisoformat(dt.replace('Z', '+00:00'))


START_DATE = '2024-12-01'
END_DATE = '2024-12-31'

pr_items = search_range('repo:cli/cli is:pr', START_DATE, END_DATE)

pr_total = len(pr_items)
pr_merged = 0
pr_closed = 0
merge_days = []
contrib_counts = {}

for item in pr_items:
    user = item.get('user') or {}
    login = user.get('login') or 'ghost'
    contrib_counts[login] = contrib_counts.get(login, 0) + 1

    pr_info = item.get('pull_request') or {}
    merged_at = pr_info.get('merged_at')
    if merged_at:
        pr_merged += 1
        created_at = item.get('created_at')
        if created_at:
            delta = parse_iso(merged_at) - parse_iso(created_at)
            merge_days.append(delta.total_seconds() / 86400.0)
    else:
        if item.get('state') == 'closed':
            pr_closed += 1

if merge_days:
    avg_merge_days = round(sum(merge_days) / len(merge_days), 1)
else:
    avg_merge_days = 0.0

if contrib_counts:
    top_contributor = sorted(contrib_counts.items(), key=lambda kv: (-kv[1], kv[0].lower()))[0][0]
else:
    top_contributor = ''

issue_items = search_range('repo:cli/cli is:issue', START_DATE, END_DATE)

issue_total = len(issue_items)
issue_bug = 0
resolved_bugs = 0

start_dt = datetime(2024, 12, 1, 0, 0, 0, tzinfo=timezone.utc)
end_dt = datetime(2024, 12, 31, 23, 59, 59, tzinfo=timezone.utc)

for item in issue_items:
    labels = item.get('labels', []) or []
    is_bug = any('bug' in (lbl.get('name') or '').lower() for lbl in labels)
    if is_bug:
        issue_bug += 1
        closed_at = parse_iso(item.get('closed_at'))
        if closed_at and start_dt <= closed_at <= end_dt:
            resolved_bugs += 1

report = {
    'pr': {
        'total': pr_total,
        'merged': pr_merged,
        'closed': pr_closed,
        'avg_merge_days': float(avg_merge_days),
        'top_contributor': top_contributor,
    },
    'issue': {
        'total': issue_total,
        'bug': issue_bug,
        'resolved_bugs': resolved_bugs,
    },
}

with open('/app/report.json', 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)
    f.write('\n')

print(json.dumps(report, indent=2))
